// ==========================================
// N8N AI AGENT → COMPLETE STRING NORMALIZER
// + CUSTOMER ID GENERATOR
// + CUSTOMER DATE/STATUS GENERATOR
// ==========================================

// ==========================================
// 1. GET AI AGENT OUTPUT
// ==========================================

let input = $json;

// ==========================================
// 2. UNWRAP COMMON AI AGENT WRAPPERS
// ==========================================

if (input.output !== undefined && input.output !== null) {
  input = input.output;
}
else if (input.text !== undefined && input.text !== null) {
  input = input.text;
}
else if (input.response !== undefined && input.response !== null) {
  input = input.response;
}
else if (input.result !== undefined && input.result !== null) {
  input = input.result;
}

// ==========================================
// 3. PARSE JSON IF STRING
// ==========================================

function parseJSON(value) {

  if (typeof value !== 'string') {
    return value;
  }

  try {
    return JSON.parse(value);
  }
  catch (error) {
    return {
      message: value
    };
  }
}

input = parseJSON(input);

// ==========================================
// 4. MAKE SURE INPUT IS AN OBJECT
// ==========================================

if (
  !input ||
  typeof input !== 'object' ||
  Array.isArray(input)
) {
  input = {
    message: String(input || '')
  };
}

// ==========================================
// 5. GET DATA OBJECT
// ==========================================

let data = input.data;

if (typeof data === 'string') {
  data = parseJSON(data);
}

if (
  !data ||
  typeof data !== 'object' ||
  Array.isArray(data)
) {
  data = {};
}

// ==========================================
// 6. COMBINE TOP LEVEL + DATA
// ==========================================

const combined = {
  ...input,
  ...data
};

// ==========================================
// 7. STRING CONVERTER
// ==========================================

function toStringValue(value) {

  if (
    value === undefined ||
    value === null
  ) {
    return '';
  }

  if (Array.isArray(value)) {

    return value
      .map(function(item) {

        if (
          item !== null &&
          typeof item === 'object'
        ) {
          return JSON.stringify(item);
        }

        return String(item || '');

      })
      .join(', ');
  }

  if (typeof value === 'object') {
    return JSON.stringify(value);
  }

  return String(value);
}

// ==========================================
// 8. GET FIELD
// ==========================================

function getField(name, fallback) {

  if (fallback === undefined) {
    fallback = '';
  }

  if (
    combined[name] !== undefined &&
    combined[name] !== null
  ) {
    return toStringValue(combined[name]);
  }

  return fallback;
}

// ==========================================
// 9. GET ACTION
// ==========================================

const action = getField('action');

// ==========================================
// 10. CUSTOMER ID
// ==========================================

let customerId = getField('customer_id');

if (
  action === 'create_customer' &&
  customerId === ''
) {

  var randomNumber = Math.floor(
    100000 + Math.random() * 900000
  );

  customerId = 'CUST-' + randomNumber;
}

// ==========================================
// 11. CUSTOMER STATUS
// ==========================================

let status = getField('status');

// ==========================================
// 12. CREATED AT
// ==========================================

let createdAt = getField('created_at');

// ==========================================
// 13. LAST CONTACT
// ==========================================

let lastContact = getField('last_contact');

// ==========================================
// 14. AUTO-GENERATE CUSTOMER INFORMATION
// ==========================================

if (action === 'create_customer') {

  // Default status
  if (status === '') {
    status = 'Active';
  }

  // Creation timestamp
  if (createdAt === '') {
    createdAt = new Date().toISOString();
  }

  // Last contact timestamp
  if (lastContact === '') {
    lastContact = new Date().toISOString();
  }
}

// ==========================================
// 15. FINAL OUTPUT
// ==========================================

return [
  {
    json: {

      // RESPONSE
      success: getField('success'),
      action: action,
      message: getField('message'),
      error: getField('error'),

      // CUSTOMER
      customer_id: customerId,
      name: getField('name'),
      company_name: getField('company_name'),
      email: getField('email'),
      phone: getField('phone'),
      industry: getField('industry'),
      company_size: getField('company_size'),
      website: getField('website'),
      location: getField('location'),
      existing_tools: getField('existing_tools'),
      budget_range: getField('budget_range'),

      // AUTO-GENERATED CUSTOMER FIELDS
      status: status,
      created_at: createdAt,
      last_contact: lastContact,

      // AUTOMATION REQUEST
      service_name: getField('service_name'),
      department: getField('department'),
      quantity: getField('quantity', '1'),
      request_location: getField('request_location'),
      urgency: getField('urgency'),
      issue: getField('issue'),
      notes: getField('notes'),
      desired_automation: getField('desired_automation'),
      expected_outcome: getField('expected_outcome'),

      // APPOINTMENT
      appointment_id: getField('appointment_id'),
      selected_date: getField('selected_date'),
      selected_time: getField('selected_time'),
      start_time: getField('start_time'),
      end_time: getField('end_time'),
      availability_id: getField('availability_id'),
      technician_id: getField('technician_id'),
      technician_name: getField('technician_name'),

      // COMPONENTS
      selected_components: getField('selected_components'),

      // QUOTATION
      quote_id: getField('quote_id'),

      // POLICY
      policy_type: getField('policy_type'),

      // ORIGINAL DATA
      data: toStringValue(input.data)
    }
  }
];

const previousData = $('Code in JavaScript6').first().json;
const currentData = $json;

return [
  {
    json: {
      previous_data: previousData,
      current_data: currentData,

      // Also provide one combined output
      ...previousData,
      ...currentData
    }
  }
];

