// Get data directly from the current input
const previousData = $input.first().json;

const appointment_id =
  'APT' + Math.floor(100000 + Math.random() * 900000).toString();

// Expected:
// selected_date = "2026-09-20"
// start_time = "14:00"
// end_time = "15:00"

const selectedDate =
  String(previousData.selected_date || '').trim();

const startTimeRaw =
  String(
    previousData.start_time ||
    previousData.selected_time ||
    ''
  ).trim();

const endTimeRaw =
  String(previousData.end_time || '').trim();

const UTC_OFFSET = '+03:00';

function padTime(t) {
  if (!t) return null;

  const parts = t.split(':');

  const hh = (parts[0] || '00').padStart(2, '0');
  const mm = (parts[1] || '00').padStart(2, '0');
  const ss = (parts[2] || '00').padStart(2, '0');

  return `${hh}:${mm}:${ss}`;
}

function toIsoWithOffset(dateStr, timeStr) {
  if (!dateStr || !timeStr) return null;

  const t = padTime(timeStr);

  if (!t) return null;

  return `${dateStr}T${t}${UTC_OFFSET}`;
}

const time_min =
  toIsoWithOffset(selectedDate, startTimeRaw);

const time_max =
  toIsoWithOffset(selectedDate, endTimeRaw);

return [
  {
    json: {
      ...previousData,

      appointment_id,
      time_min,
      time_max,

      selected_date: selectedDate,
      start_time: startTimeRaw,
      end_time: endTimeRaw,

      missing_time_fields:
        String(!time_min || !time_max)
    }
  }
];

