const previousData = $('Code in JavaScript10').first().json;

const appointment_id = 'APT' + Math.floor(100000 + Math.random() * 900000).toString();

// Expect selected_date like "2026-09-20", and start_time / end_time like "14:00"
const selectedDate = (previousData.selected_date || '').toString().trim();
const startTimeRaw = (previousData.start_time || previousData.selected_time || '').toString().trim();
const endTimeRaw = (previousData.end_time || '').toString().trim();

const UTC_OFFSET = '+03:00';

function padTime(t) {
  if (!t) return null;
  // Accept "14:00" or "14:00:00"
  const parts = t.split(':');
  const hh = (parts[0] || '00').padStart(2, '0');
  const mm = (parts[1] || '00').padStart(2, '0');
  const ss = (parts[2] || '00').padStart(2, '0');
  return `${hh}:${mm}:${ss}`;
}

function toIsoWithOffset(dateStr, timeStr) {
  if (!dateStr || !timeStr) return null;
  const t = padTime(timeStr);
  if (!t) return null;
  // Full RFC3339 datetime with explicit UTC offset - this is the format
  // Google Calendar's API expects; a bare local-time string without an
  // offset is what was causing the "can't process the mentioned value" error.
  return `${dateStr}T${t}${UTC_OFFSET}`;
}

const time_min = toIsoWithOffset(selectedDate, startTimeRaw);
const time_max = toIsoWithOffset(selectedDate, endTimeRaw);

return [
  {
    json: {
      appointment_id,
      time_min,
      time_max,
      selected_date: selectedDate,
      start_time: startTimeRaw,
      end_time: endTimeRaw,
      customer_id: previousData.customer_id,
      name: previousData.name,
      company_name: previousData.company_name,
      email: previousData.email,
      service_name: previousData.service_name,
      notes: previousData.notes,
      missing_time_fields: !time_min || !time_max
    }
  }
];

